// Variant B: remove the conflicts and state the rule as a test, using the
// spec reconciler's baseline wording. No example names a finding from run 6.
let b = control;
b = replaceOnce(
  b,
  "Trace attacker-controlled inputs and privilege or data transitions through the changed code and report only defects the current code can fix.",
  "Trace attacker-controlled inputs and privilege or data transitions through the changed code and report only defects the current code can fix, judged against the rule below on what the approved specification requires."
);
b = replaceOnce(
  b,
  "Report only actionable defects with a reproducible impact that can be corrected in the current changed code. Do not report style, preference, optional refactoring, speculative hardening, questions, or a concern that requires changing the approved specification or plan.",
  "Report a defect only when the changed code fails a behavior the approved specification or plan states, or breaks in ordinary use: it crashes, loses or corrupts data, returns a wrong result, or lets a user read or change data or act in a way the specification does not allow. When the specification states a workable baseline and the concern is whether to add protection, limits, or policy beyond it, that concern is not a defect: do not report it, however reasonable it looks. Do not report style, preference, optional refactoring, or questions."
);
b = replaceOnce(
  b,
  "report every actionable defect you identify across all declared acceptance criteria and plan tasks",
  "report every defect that meets the rule above across all declared acceptance criteria and plan tasks"
);
b = replaceOnce(
  b,
  "  - medium: a concrete defect that does not fail an acceptance criterion",
  "  - medium: the code breaks in ordinary use as described above without failing an acceptance criterion"
);

// Variant AB: B plus a required basis field per finding.
let ab = b;
ab = replaceOnce(
  ab,
  '"intentKey": "...", "subject": "..."}]}}',
  '"intentKey": "...", "subject": "...", "basis": "..."}]}}'
);
ab = replaceOnce(
  ab,
  "- subject: one sentence naming both the concrete defect and its reproducible\n  impact",
  "- subject: one sentence naming both the concrete defect and its reproducible\n  impact\n- basis: why this is a defect, as exactly one of: the ID of the acceptance criterion the code fails, copied exactly from the approved specification (for example AC-001); the words plan task followed by the task's first five words, copied exactly; or one of crash, data-loss, wrong-result, unauthorized-access, naming how the code breaks in ordinary use. A concern with no such basis is not reported."
);
